-- HE1 Task 30: the date and time functions. Rows cover a plain time, the
-- epoch, both New York DST changes, the Date/DateTime limits, values before
-- 1970 (Date32, DateTime64), month ends and a leap day, and NULLs.
DROP TABLE IF EXISTS t30;
CREATE TABLE t30 (
    id UInt32,
    d Date, d32 Date32,
    dt DateTime, dtz DateTime('Asia/Kolkata'), dny DateTime('America/New_York'),
    dt64 DateTime64(3), dt64u DateTime64(6, 'UTC'),
    ns Nullable(DateTime), s String, ms Int64, nanos Int64
) ENGINE = MergeTree ORDER BY id;
